</table></main><script>document.querySelectorAll('.review-form').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{Accept:'application/json'}});if(response.ok)location.reload();else alert((await response.json().catch(()=>({}))).message||'ثبت نتیجه ناموفق بود.')}));</script></body></html>
